class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        ans = -1
        for char in set(s):
            for length in range(1, n + 1):
                sub = char * length
                count = 0
                for i in range(n - length + 1):
                    if s[i:i+length] == sub:
                        count += 1
                if count >= 3:
                    ans = max(ans, length)
        return ans
